import React, { useState, useEffect, useRef } from "react";
import { MapContainer, TileLayer, GeoJSON, LayersControl } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import Slider from "react-slider";
import "./App.css";
import { useMapEvents } from "react-leaflet";

function ZoomWatcher({ onZoomChange }) {
  useMapEvents({
    zoomend: (e) => {
      const newZoom = e.target.getZoom();
      onZoomChange(newZoom);
    },
  });
  return null;
}

const baseColors = {
  Собянин: "#0072bc",
  Навальный: "#f28c28",
  Мельников: "#d73027"
};

function shadeColor(hex, alpha) {
  if (!hex) return "#cccccc";
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

function getColorByValue(value, thresholds) {
  for (let i = 0; i < thresholds.length; i++) {
    if (value < thresholds[i].limit) return thresholds[i].color;
  }
  return thresholds[thresholds.length - 1].color;
}

const turnoutThresholds = [
  { limit: 20, color: "#e6f4ea" },
  { limit: 35, color: "#a6d9b7" },
  { limit: 50, color: "#5bbf83" },
  { limit: 65, color: "#3a9d66" },
  { limit: 101, color: "#21814f" },
];

const invalidThresholds = [
  { limit: 0.5, color: "#fde8ef" },
  { limit: 1, color: "#fcd2e1" },
  { limit: 1.5, color: "#f7b6cf" },
  { limit: 2, color: "#ef6cae" },
  { limit: 100, color: "#c51b8a" },
];

function getStyleByDataType(props, dataType) {
  if (dataType === "Явка") {
    const value = props["2013_mer_явка"] || 0;
    return {
      color: "#000",
      weight: 1,
      fillOpacity: 1,
      fillColor: getColorByValue(value, turnoutThresholds),
    };
  }
  if (dataType === "Процент испорченных бюллетеней") {
    const value = props["2013_mer_недействительные"] || 0;
    return {
      color: "#000",
      weight: 1,
      fillOpacity: 1,
      fillColor: getColorByValue(value, invalidThresholds),
    };
  }
  return null;
}

function App() {
  const [year, setYear] = useState(2012);
  const [geoData, setGeoData] = useState(null);
  const [activeDataType, setActiveDataType] = useState("Победитель");
  const [activeElectionLevel, setActiveElectionLevel] = useState("Госдума");
  const [activeListType, setActiveListType] = useState("Округ");
  const [mapZoom, setMapZoom] = useState(10);
  const [districtData, setDistrictData] = useState(null);
  const [uikData, setUikData] = useState(null);
  const mapRef = useRef();

  useEffect(() => {
    if (year === 2013 && activeElectionLevel === "Мэр") {
      fetch("/data/districts_with_2013_mer.geojson")
        .then((res) => res.json())
        .then((data) => setDistrictData(data));

      fetch("/data/united_uiks_with_final_2013_mer.geojson")
        .then((res) => res.json())
        .then((data) => setUikData(data));
    }
  }, [year, activeElectionLevel]);

  const showDistrictLayer = year === 2013 && activeElectionLevel === "Мэр";
  const showPrecinctLayer = showDistrictLayer && mapZoom > 13;

  return (
    <div className="App">
      <div className="map-wrapper">
        <div className="map-container">
          <MapContainer
            center={[55.7558, 37.6173]}
            zoom={10}
            className="map-container"
            whenCreated={(map) => {
              mapRef.current = map;
              map.on("zoomend", () => setMapZoom(map.getZoom()));
            }}
          >
            <TileLayer
              attribution='Tiles &copy; Esri'
              url="https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer/tile/{z}/{y}/{x}"
            />
            <ZoomWatcher onZoomChange={setMapZoom} />

            {showDistrictLayer && districtData && (
              <GeoJSON
                data={districtData}
                style={(feature) =>
                  activeDataType === "Победитель"
                    ? {
                        color: "#000",
                        weight: 2,
                        fillOpacity: 1,
                        fillColor: "#ccc", // заменить при необходимости
                      }
                    : getStyleByDataType(feature.properties, activeDataType)
                }
              />
            )}

            {showPrecinctLayer && uikData && (
              <GeoJSON
                data={uikData}
                style={(feature) =>
                  activeDataType === "Победитель"
                    ? {
                        color: "#000",
                        weight: 1,
                        fillOpacity: 1,
                        fillColor: "#ccc", // заменить при необходимости
                      }
                    : getStyleByDataType(feature.properties, activeDataType)
                }
              />
            )}
          </MapContainer>
        </div>
      </div>
    </div>
  );
}

export default App;
